WITH l AS (SELECT * FROM bestiary_fights WHERE zone_id = {zone:Int64} AND mob_name = {name:String} AND capture_id NOT IN (SELECT capture_id FROM capture_trust FINAL WHERE trust = 'flagged') ORDER BY ts_ms DESC LIMIT 200), kc AS (SELECT fight_key AS k_key, min(capture_id) AS k_owner, arraySort(groupUniqArray(capture_id)) AS k_copies FROM bestiary_fights WHERE zone_id = {zone:Int64} AND mob_name = {name:String} AND capture_id NOT IN (SELECT capture_id FROM capture_trust FINAL WHERE trust = 'flagged') AND fight_key IN (SELECT fight_key FROM l) GROUP BY fight_key), cp AS (SELECT capture_id AS cp_capture, character AS cp_character, start_ms AS cp_start FROM captures WHERE capture_id IN (SELECT capture_id FROM l)) SELECT coalesce(l.model_id, -1) AS model, l.capture_id AS capture_id, cp.cp_character AS recorder, cp.cp_start AS capture_start, l.idx AS idx, l.mob_id AS mob_id, l.ts_ms AS start, l.end_ms AS end, l.end_ms AS "end", l.outcome AS outcome, l.capture_id = kc.k_owner AS kept, kc.k_copies AS copies, l.level AS level, concat('https://lens.sruon.dev/c/', l.capture_id, '#packet=', toString(l.idx)) AS lens_url, length(l.delays) AS delays, length(l.rounds) AS rounds, length(l.tp_gains) AS tp_gains, arraySum(arrayMap(r -> coalesce(r.passed + r.missed, 0), l.swings_at_recorder)) AS swings, arrayMap(u -> [u.id, u.idx], l.tp) AS tp, l.spells AS spells, l.idle_spells AS idle_spells, l.taken AS taken, arrayMap(x -> [toInt64(x.item), x.idx], l.drops) AS drops, l.claimed AS claimed, l.th_level AS th, l.hp_min AS hp_min, l.hp_max AS hp_max, l.respawn_ms AS respawn_ms, l.respawn_idx AS respawn_idx, arrayMap(s -> [s.idx, s.chain, s.category, s.closing, s.damage], l.skillchains) AS skillchains FROM l LEFT JOIN kc ON kc.k_key = l.fight_key LEFT JOIN cp ON cp.cp_capture = l.capture_id ORDER BY start, capture_id
